$(document).ready(function( )
{
	$("#frmSearch #BtnSearch").button({ icons:{ primary:'ui-icon-search' } });
	$("#frmSearch #BtnReset").button({ icons:{ primary:'ui-icon-refresh' } });


	$("#frmSearch #ddSchool").change(function( )
	{
		getClassSectionsList("#frmSearch #ddSchool", "#frmSearch #ddClass");
	});


	$("#frmSearch #ddSchool, #frmSearch #ddClass").change(function( )
	{
		getTimetableSeasonsList("#frmSearch #ddSchool", "#frmSearch #ddClass", "#frmSearch #ddSeason");
	});


	$("#frmSearch #ddSchool, #frmSearch #ddClass, #frmSearch #ddSession, #frmSearch #ddSeason").change(function( )
	{
		getTimetablesList("#frmSearch #ddSchool", "#frmSearch #ddClass", "#frmSearch #ddSession", "#frmSearch #ddSeason", "#frmSearch #ddTimetable");
	});


	$("#frmSearch #BtnReset").click(function( )
	{
		$("#frmSearch")[0].reset( );
		$("#SearchMsg").hide( );

		clearList("#frmSearch #ddSeason");
		clearList("#frmSearch #ddTimetable");

		if ($("#frmSearch select#ddSchool").length > 0)
		{
			clearList("#frmSearch #ddClass");

			$("#frmSearch #ddSchool").focus( );
		}

		else
			$("#frmSearch #ddClass").focus( );

		return false;
	});


	$("#frmSearch").submit(function( )
	{
		var objFV = new FormValidator("frmSearch", "SearchMsg");


		if (!objFV.validate("ddSchool", "B", "Please select the School."))
			return false;

		if (!objFV.validate("ddClass", "B", "Please select the Class/Section."))
			return false;

		if (!objFV.validate("ddSession", "B", "Please select the Session."))
			return false;

		if (!objFV.validate("ddSeason", "B", "Please select the Season."))
			return false;

		if (!objFV.validate("ddTimetable", "B", "Please select the Timetable."))
			return false;


		$("#BtnSearch").attr('disabled', true);
		$("#SearchMsg").hide( );
	});


	$(".draggable").draggable(
	{
		scroll             :  false,
		scrollSensitivity  :  100,
		scrollSpeed        :  100,
		containment        :  "#frmRecord",
		cursor             :  "move",
		revert             :  "invalid",
		helper             :  "clone",

		start              :  function(event, ui)
		{

		},

		drag               :  function(event, ui)
		{

		},

		stop               :  function(event, ui)
		{

		}
	});


	$(".droppable").droppable(
	{
		activeClass  :  "active",
		hoverClass   :  "hover",
		
		drop         :  function(event, ui)
		{
			if (ui.draggable.hasClass("subject"))
			{
				var sParams    = ui.draggable.attr("rel").split("|");
				var objSubject = $(this).find(".subject");
				
				var iDay       = objSubject.attr("day");
				var iTiming    = objSubject.attr("timing");
				var iSubject   = objSubject.attr("rel");
				var sSubject   = objSubject.html( );
				
				objSubject.html(sParams[1])
						  .attr("rel", sParams[0])
						  .addClass("selected");
								
							
				$.post("ajax/timetable/update-schedule.php",
					{ Action:"Subject", Timetable:$("#TimetableId").val( ), Day:iDay, Timing:iTiming, Subject:sParams[0] },

					function (sResponse)
					{
						var sParams = sResponse.split("|");
						
						if (sParams[0] == "OK")
						{
							objSubject.addClass("saved");
							objSubject.html(objSubject.html( ) + "<img src='images/icons/delete.png' alt='Remove' title='Remove' />");
						}
						
						else
						{
							objSubject.addClass("error");
							
							showMessage("#RecordMsg", "info", sParams[1]);
						}


						  setTimeout(function( )
						  {
							  if (objSubject.hasClass("error"))
							  {
								objSubject.html(sSubject)
										  .attr("rel", iSubject);
							  }
							  
							  objSubject.removeClass("saved").removeClass("error");
						  }, 3000);
					},

					"text");
			}
			
			else if (ui.draggable.hasClass("teacher"))
			{
				var sParams    = ui.draggable.attr("rel").split("|");
				var objTeacher = $(this).find(".teacher");
				
				var iDay       = objTeacher.attr("day");
				var iTiming    = objTeacher.attr("timing");
				var iTeacher   = objTeacher.attr("rel");
				var sTeacher   = objTeacher.html( );
				
				objTeacher.html(sParams[1])
						  .attr("rel", sParams[0])
						  .addClass("selected");
									
						        
				$.post("ajax/timetable/update-schedule.php",
					{ Action:"Teacher", Timetable:$("#TimetableId").val( ), Day:iDay, Timing:iTiming, Teacher:sParams[0] },

					function (sResponse)
					{
						var sParams = sResponse.split("|");
						
						if (sParams[0] == "OK")
						{
							objTeacher.addClass("saved");
							objTeacher.html(objTeacher.html( ) + "<img src='images/icons/delete.png' alt='Remove' title='Remove' />");
						}
						
						else
						{
							objTeacher.addClass("error");
							
							showMessage("#RecordMsg", "info", sParams[1]);
						}


						  setTimeout(function( )
						  {
							  if (objTeacher.hasClass("error"))
							  {
								objTeacher.html(sTeacher)
										  .attr("rel", iTeacher);								  
							  }
							  
							  objTeacher.removeClass("saved").removeClass("error");
						  }, 3000);
					},

					"text");
			}
		}
	});
	
	
	$(document).on("click", ".droppable .subject img", function( )
	{
	     var objSubject = $(this).parent( );
		
	     $.post("ajax/timetable/update-schedule.php",
		    { Action:"Subject", Timetable:$("#TimetableId").val( ), Day:objSubject.attr("day"), Timing:objSubject.attr("timing"), Subject:"0" },

		    function (sResponse)
		    {
			  if (sResponse.indexOf("OK") >= 0)
				objSubject.addClass("saved");

			  else
				objSubject.addClass("error");


			  setTimeout(function( )
			  {
			  	objSubject.find("img").remove( );
				objSubject.removeClass("saved").removeClass("error");
				
				if (sResponse.indexOf("OK") >= 0)
				{
					objSubject.attr("rel", "0");
					objSubject.html("");
					objSubject.removeClass("selected");
				}
			  }, 3000);
		    },

		    "text");
	});
	
	
	$(document).on("click", ".droppable .teacher img", function( )
	{
	     var objTeacher = $(this).parent( );
		
	     $.post("ajax/timetable/update-schedule.php",
		    { Action:"Teacher", Timetable:$("#TimetableId").val( ), Day:objTeacher.attr("day"), Timing:objTeacher.attr("timing"), Teacher:"0" },

		    function (sResponse)
		    {
			  if (sResponse.indexOf("OK") >= 0)
				objTeacher.addClass("saved");

			  else
				objTeacher.addClass("error");


			  setTimeout(function( )
			  {
			  	objTeacher.find("img").remove( );
				objTeacher.removeClass("saved").removeClass("error");
				
				if (sResponse.indexOf("OK") >= 0)
				{
					objTeacher.attr("rel", "0");
					objTeacher.html("");
					objTeacher.removeClass("selected");
				}
			  }, 3000);
		    },

		    "text");
	});	
});

