$(document).ready(function( )
{
	$("#frmReport #BtnExport, #frmReport #BtnView").button({ icons:{ primary:'ui-icon-disk' } });
	$("#frmReport #BtnReset").button({ icons:{ primary:'ui-icon-refresh' } });

	$("#txtStartDate, #txtEndDate").datepicker(
	{
		showOn          : "both",
		buttonImage     : "images/icons/calendar.gif",
		buttonImageOnly : true,
		dateFormat      : "yy-mm-dd",
		changeMonth     : true,
		changeYear      : true
	});


	$("#frmReport #BtnReset").click(function( )
	{
		$("#frmReport")[0].reset( );
		$("#ReportMsg").hide( );


		$("#MonthYear").removeClass("hidden");
		$("#DateRange").addClass("hidden");
		$("#FeeConcession").addClass("hidden");

		$("#frmReport #ddDateField option").remove( );
		$("<option/>").val("month_year").html("Billing Month").appendTo("#frmReport #ddDateField");
		$("<option/>").val("issue_date").html("Issue Date").appendTo("#frmReport #ddDateField");
		$("<option/>").val("due_date").html("Due Date").appendTo("#frmReport #ddDateField");
		$("<option/>").val("paid_date").html("Paid Date").appendTo("#frmReport #ddDateField");

		$("#frmReport #ddType option").remove( );
		$("<option/>").val("").html("All Types").appendTo("#frmReport #ddType");
		$("<option/>").val("A").html("Admission").appendTo("#frmReport #ddType");
		$("<option/>").val("C").html("Custom").appendTo("#frmReport #ddType");
		$("<option/>").val("R").html("Regular").appendTo("#frmReport #ddType");		


		return false;
	});


	$("#frmReport #ddDateField").change(function( )
	{
		if ($(this).val( ) == "overall")
		{
			$("#MonthYear").addClass("hidden");
			$("#DateRange").addClass("hidden");
			$("#Session").addClass("hidden");
			$("#txtStartDate, #txtEndDate, #ddSession").val("");
		}

		else if ($(this).val( ) == "month_year")
		{
			$("#MonthYear").removeClass("hidden");

			$("#DateRange").addClass("hidden");
			$("#Session").addClass("hidden");
			$("#txtStartDate, #txtEndDate, #ddSession").val("");
		}

		else if ($(this).val( ) == "session")
		{
			$("#Session").removeClass("hidden");

			$("#MonthYear").addClass("hidden");
			$("#DateRange").addClass("hidden");
			$("#txtStartDate, #txtEndDate").val("");
		}

		else
		{
			$("#DateRange").removeClass("hidden");

			$("#MonthYear").addClass("hidden");
			$("#Session").addClass("hidden");
			$("#ddSession").val("");
		}
	});


	$("#frmReport #ddReportType").change(function( )
	{
		$("#frmReport #ddType option").remove( );		

		if ($(this).val( ) == "bill-not-generated")
			$("<option/>").val("R").html("Regular").appendTo("#frmReport #ddType");

		else if ($(this).val( ) == "final-settlements")
			$("<option/>").val("").html("All").appendTo("#frmReport #ddType");

		else
		{
			$("<option/>").val("").html("All Types").appendTo("#frmReport #ddType");
			$("<option/>").val("A").html("Admission").appendTo("#frmReport #ddType");
			$("<option/>").val("C").html("Custom").appendTo("#frmReport #ddType");
			$("<option/>").val("R").html("Regular").appendTo("#frmReport #ddType");			
		}



		$("#frmReport #ddDateField option").remove( );

		$("#DateField").removeClass("hidden");
		$("#MonthYear").removeClass("hidden");
		$("#DateRange").addClass("hidden");
		$("#FeeConcession").addClass("hidden");
		$("#PaymentMode").addClass("hidden");
		$("#BankAccount").addClass("hidden");


		if ($(this).val( ) == "defaulters-list-month-wise")
			$("#DateField, #MonthYear").addClass("hidden");

		else if ($(this).val( ) == "defaulters-list" || $(this).val( ) == "bill-not-generated")
		{
			$("<option/>").val("month_year").html("Billing Month").appendTo("#frmReport #ddDateField");		
			$("<option/>").val("issue_date").html("Issue Date").appendTo("#frmReport #ddDateField");
			$("<option/>").val("due_date").html("Due Date").appendTo("#frmReport #ddDateField");
		}

		else if ($(this).val( ) == "fee-bills-log")
			$("<option/>").val("date_time").html("Action Date").appendTo("#frmReport #ddDateField");

		else if ($(this).val( ) == "final-settlements")
			$("<option/>").val("ss.date").html("Settlement Date").appendTo("#frmReport #ddDateField");		

		else
		{
			if ($(this).val( ) == "security-fee-deposits")
				$("<option/>").val("overall").html("Overall").appendTo("#frmReport #ddDateField");

			$("<option/>").val("month_year").html("Billing Month").appendTo("#frmReport #ddDateField");
			$("<option/>").val("issue_date").html("Issue Date").appendTo("#frmReport #ddDateField");
			$("<option/>").val("due_date").html("Due Date").appendTo("#frmReport #ddDateField");
			$("<option/>").val("paid_date").html("Paid Date").appendTo("#frmReport #ddDateField");


			if ($(this).val( ) == "fee-collection-details" || $(this).val( ) == "fee-bills-receipt" || $(this).val( ) == "security-fee-deposits")
			{
				$("#PaymentMode").removeClass("hidden");
				$("#BankAccount").removeClass("hidden");
			}
		}


		if ($(this).val( ) == "fee-bills-log")
		{
			$("#MonthYear").addClass("hidden");
			$("#DateRange").removeClass("hidden");
		}

		if ($(this).val( ) == "fee-concession-details")
			$("#FeeConcession").removeClass("hidden");


		$("#frmReport #ddDateField").trigger("change");
	});


	$("#frmReport span a").click(function( )
	{
		var sData   = $(this).attr("rel");
		var sParams = sData.split("|");

		$("#frmReport ." + sParams[1]).each(function( )
		{
			if (sParams[0] == "Check")
				$(this).prop("checked", true);

			else
				$(this).prop("checked", false);
		});

		return false;
	});


	$("#frmReport").submit(function( )
	{
		var objFV = new FormValidator("frmReport", "ReportMsg");
		var bFlag = false;

		if (!objFV.validate("ddReportType", "B", "Please select the Report Type."))
			return false;

		$("#frmReport .school").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false)
		{
			showMessage("#ReportMsg", "alert", "Please select at-least one School.");

			return false;
		}


		if (objFV.value("ddReportType") != "defaulters-list-month-wise")
		{
			if (!objFV.validate("ddDateField", "B", "Please select the Date Search Field."))
				return false;
		}

		if (objFV.value("ddDateField") == "session")
		{
			if (!objFV.validate("ddSession", "B", "Please select the Session."))
				return false;
		}

		else if (objFV.value("ddDateField") != "month_year" && objFV.value("ddDateField") != "overall")
		{
			if (!objFV.validate("txtStartDate", "B", "Please select the Search Start Date."))
				return false;

			if (!objFV.validate("txtEndDate", "B", "Please select the Search End Date."))
				return false;
		}



		$("#BtnExport").attr('disabled', true);
		$("#ReportMsg").hide( );

		setTimeout(function( ) { $("#BtnExport").attr('disabled', false); }, 30000);
	});



	$(document).on("click", "#frmReport #BtnView", function(event)
	{
		var objFV = new FormValidator("frmReport", "ReportMsg");
		var bFlag = false;


		if (!objFV.validate("ddReportType", "B", "Please select the Report Type."))
			return false;

		if (!objFV.validate("ddSession", "B", "Please select the Session."))
			return false;

		$("#frmReport .school").each(function(iIndex)
		{
			if ($(this).prop("checked") == true)
				bFlag = true;
		});

		if (bFlag == false)
		{
			showMessage("#ReportMsg", "alert", "Please select at-least one School.");

			return false;
		}


		if (!objFV.validate("ddDateField", "B", "Please select the Date Search Field."))
			return false;

		if (objFV.value("ddDateField") == "session")
		{
			if (!objFV.validate("ddSession", "B", "Please select the Session."))
				return false;
		}

		else if (objFV.value("ddDateField") != "month_year" && objFV.value("ddDateField") != "overall")
		{
			if (!objFV.validate("txtStartDate", "B", "Please select the Search Start Date."))
				return false;

			if (!objFV.validate("txtEndDate", "B", "Please select the Search End Date."))
				return false;
		}


		$.colorbox({ href:("students/export-report.php?" + $("#frmReport").serialize() + "&Html=Y"), title:"[ <a href='javascript:window.frames[0].focus( ); window.frames[0].print( );'><b style='color:#ffffff;'>Print</b></a> ]", width:"99%", height:"99%", iframe:true, opacity:"0.50", overlayClose:false });


		return false;
	});
});

