var objTable;
var sFromDate = "";
var sToDate   = "";

$(document).ready(function( )
{
	$("#txtDate").datepicker(
	{
		showOn           :  "both",
		buttonImage      :  "images/icons/calendar.gif",
		buttonImageOnly  :  true,
		dateFormat       :  "yy-mm-dd",
		minDate          :   parseDate($("#txtDate").attr("date"), true)
	});


	$("#frmRecord #BtnGenerate").button({ icons:{ primary:'ui-icon-disk' } });


	$("#frmRecord #ddSchool").change(function( )
	{
		getClassSectionsList("#frmRecord #ddSchool", "#frmRecord #ddClass");
	});


	$("#frmRecord #ddSchool, #frmRecord #ddSession, #frmRecord #ddClass").change(function( )
	{
		getStudentsList("#frmRecord #ddSchool", "#frmRecord #ddSession", "#frmRecord #ddClass", "#frmRecord #ddStudent", "W,G");
	});


	$("#frmRecord #ddStudent").change(function( )
	{
		$("#frmRecord #RecordMsg").hide( );
		$("#frmRecord #SettlementDetails").html("");


		if ($(this).val( ) != "")
		{
			$("#frmRecord #BtnGenerate").attr('disabled', true);


			$.post("ajax/billing/get-final-settlement-details.php",
				{ School:$("#frmRecord #ddSchool").val( ), Session:$("#frmRecord #ddSession").val( ), Class:$("#frmRecord #ddClass").val( ), Student:$("#frmRecord #ddStudent").val( ) },

				function (sResponse)
				{
					var sParams = sResponse.split("|-|");

					if (sParams[0] != "success")
						showMessage("#RecordMsg", sParams[0], sParams[1]);

					else
						$("#frmRecord #SettlementDetails").html(sParams[1]);


					$("#frmRecord #BtnGenerate").attr('disabled', false);
				},

				"text");
		}
	});


	if ($("#frmRecord #ddStudent").val( ) != "")
		$("#frmRecord #ddStudent").trigger("change");




	$(document).on("change", "#frmRecord #ddPaymentMode", function( )
	{
		if ($(this).val( ) != "")
		{
			if ($("#frmRecord #Receiver").css("display") != "block")
				$("#frmRecord #Receiver").show('blind');
		}

		else
		{
			if ($("#frmRecord #Receiver").css("display") == "block")
				$("#frmRecord #Receiver").hide('blind');


			$("#frmRecord #txtReceiver").val("");
			$("#frmRecord #ddBankAccount").val("");
			$("#frmRecord #ddChequeNo").val("");
		}


		if ($(this).val( ) == "BT" || $(this).val( ) == "CH")
		{
			if ($("#frmRecord #BankAccount").css('display') == "none")
				$("#frmRecord #BankAccount").show('blind');

			if ($(this).val( ) == "CH")
			{
				if ($("#frmRecord #ChequeDetails").css('display') == "none")
					$("#frmRecord #ChequeDetails").show('blind');
			}
		}

		else
		{
			if ($("#frmRecord #BankAccount").css('display') == "block")
				$("#frmRecord #BankAccount").hide( );
		}


		if ($(this).val( ) != "CH")
		{
			if ($("#frmRecord #ChequeDetails").css('display') == "block")
				$("#frmRecord #ChequeDetails").hide("blind");
		}
	});


	$(document).on("change", "#frmRecord #ddBankAccount", function( )
	{
		clearList("#frmRecord #ddChequeBook");

		if ($("#frmRecord #ddBankAccount").val( ) == "")
			return;


		$.post("ajax/get-cheque-books.php",
			{ BankAccount:$("#frmRecord #ddBankAccount").val( ) },

			function (sResponse)
			{
				$("#frmRecord #ddChequeBook").html(sResponse);
			},

			"text");
	});


	$(document).on("change", "#frmRecord #ddChequeBook", function( )
	{
		clearList("#frmRecord #ddChequeNo");

		if ($("#frmRecord #ddChequeBook").val( ) == "")
			return;


		$.post("ajax/get-cheque-nos.php",
			{ ChequeBook:$("#frmRecord #ddChequeBook").val( ) },

			function (sResponse)
			{
				$("#frmRecord #ddChequeNo").html(sResponse);
			},

			"text");
	});


	$(document).on("change", "#frmRecord #txtDeductions", function( )
	{
		var iOriginalDeductions = parseInt($("#frmRecord #txtDeductions").attr("original"));
		var iCurrentDeductions  = parseInt($("#frmRecord #txtDeductions").val( ));
		var iBalance            = parseInt($("#frmRecord #txtBalance").attr("original"));

		if (isNaN(iOriginalDeductions))
			iOriginalDeductions = 0;

		if (isNaN(iCurrentDeductions))
			iCurrentDeductions = 0;

		if (isNaN(iBalance))
			iBalance = 0;


		iBalance += iOriginalDeductions;
		iBalance -= iCurrentDeductions;


		$("#frmRecord #txtBalance").val(iBalance);
		$("#frmRecord #txtBalance").trigger("blur");
	});		


	$(document).on("blur", "#frmRecord #txtBalance", function( )
