function updateRecord(iSettlementId, iRow, sFields)
{
	if (parseInt($("#TotalRecords").val( )) <= 100)
	{
		$("#DataGrid thead tr th").each(function(iIndex)
		{
			if ($(this).text( ) == "Date")
				objTable.fnUpdate(sFields[0], iRow, iIndex, false);

			else if ($(this).text( ) == "Balance")
				objTable.fnUpdate(sFields[1], iRow, iIndex, false);
		});


		$("#DataGrid .details").each(function(iIndex)
		{
			if ($(this).attr("id") == iSettlementId)
				$(this).attr("title", sFields[2]);
		});

		$(".details").tipTip( );
	}

	else
		objTable.fnDraw( );


	$.post("ajax/billing/get-final-settlement-filters.php",
	       {},

	       function (sResponse)
	       {
	       		var sSchool = "";
	       		var sClass  = "";


	       		if ($("div.toolbar #School").length > 0)
	       			sSchool = $("div.toolbar #School").val( );

	       		if ($("div.toolbar #Class").length > 0)
	       			sClass = $("div.toolbar #Class").val( );


			$("div.toolbar").html(sResponse);


	       		if ($("div.toolbar #School").length > 0)
	       			$("div.toolbar #School").val(sSchool);

	       		if ($("div.toolbar #Class").length > 0)
	       			$("div.toolbar #Class").val(sClass);
	       },

	       "text");
}
